180	     * @param request {@link HttpServletRequest} object referring to the current request.
181	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
182	     */
183	    @ExceptionHandler(MissingOwnerFieldsException.class)
184	    @ResponseBody
185	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
186	        HttpStatus status = HttpStatus.BAD_REQUEST;
